 */
function calculateWVSProxyScore(state: GameState, wvs: WVSProxyData): DiagnosticLens {
  const social = state.socialAccumulation;

  const indicators: ParadigmIndicator[] = [
    // From WVS (60% weight)
    {
      id: 'wvs_social_trust',
