      highrisk: 450,
      status: 'HIGH_RISK',
      uncertainty: 0.1,    // ±10%
    },
    biosphereIntegrity: {
      current: 10,         // E/MSY (extinctions per million species-years)
      safe: 1,
      highrisk: 10,
      status: 'HIGH_RISK',
      uncertainty: 0.5,    // ±50% (large uncertainty)
    },
    // ... 7 more boundaries
  },
};
```

