 * - Cache expires after 1 year (annual releases)
 * - Subsequent loads instant from cache
 *
 * @module data/loaders/undpLoader
 */

import { cacheManager } from './cacheManager';

/**
 * HDI country data
 */
export interface HDICountryData {
