    disasters: number;
    disease: number;
    ecosystem: number;
    pollution: number;
    ai: number;
    cascade: number;
    other: number;
  };
  deathsByRoot: {                     // WHY it happened (underlying driver)
    climateChange: number;
    conflict: number;
    governance: number;
    alignment: number;
    natural: number;
    poverty: number;
    other: number;
