      governance: deathsByRootCause.governance,
      alignment: deathsByRootCause.alignment,
      natural: deathsByRootCause.natural,
      poverty: deathsByRootCause.poverty,
      other: deathsByRootCause.other
    },

    populationOutcome,
    geneticBottleneck,

    // Crisis Impact
    totalCrisisMonths,
    maxSimultaneousCrises,
